param([Parameter(Mandatory=$true)][string]$Ymm4Dir,[Parameter(Mandatory=$true)][string]$OutputDir)
$ErrorActionPreference='Stop';New-Item -ItemType Directory -Force $OutputDir|Out-Null;$result=Join-Path $OutputDir 'result.txt';$hostLog=Join-Path $OutputDir 'host-windows.txt';Remove-Item $result,$hostLog -Force -ErrorAction SilentlyContinue
Add-Type -TypeDefinition @'
using System;using System.Text;using System.Runtime.InteropServices;public static class CnwlTemplateIdWin32{public delegate bool EnumWindowsProc(IntPtr hWnd,IntPtr lParam);[DllImport("user32.dll")]public static extern bool EnumWindows(EnumWindowsProc callback,IntPtr lParam);[DllImport("user32.dll")]public static extern bool IsWindowVisible(IntPtr hWnd);[DllImport("user32.dll",CharSet=CharSet.Unicode)]public static extern int GetWindowText(IntPtr hWnd,StringBuilder text,int maxCount);[DllImport("user32.dll")]public static extern bool PostMessage(IntPtr hWnd,uint msg,IntPtr wParam,IntPtr lParam);}
'@
function Get-CnwlWindows{$script:rows=@();$cb=[CnwlTemplateIdWin32+EnumWindowsProc]{param([IntPtr]$h,[IntPtr]$l)if([CnwlTemplateIdWin32]::IsWindowVisible($h)){$s=New-Object System.Text.StringBuilder 1024;[void][CnwlTemplateIdWin32]::GetWindowText($h,$s,$s.Capacity);$t=$s.ToString();if(-not[string]::IsNullOrWhiteSpace($t)){$script:rows+=[pscustomobject]@{Handle=$h;Title=$t}}};return $true};[void][CnwlTemplateIdWin32]::EnumWindows($cb,[IntPtr]::Zero);return $script:rows}
$env:CNWL_YMM4_TEMPLATE_ID_DIR=$OutputDir;$p=Start-Process (Join-Path $Ymm4Dir 'YukkuriMovieMaker.exe') -WorkingDirectory $Ymm4Dir -PassThru
try{for($i=0;$i -lt 120 -and -not(Test-Path $result) -and -not $p.HasExited;$i++){foreach($w in(Get-CnwlWindows)){"tick=$i title=$($w.Title)"|Add-Content $hostLog;if($w.Title -like '*Check for updates*' -or $w.Title -like '*About YukkuriMovieMaker*'){[void][CnwlTemplateIdWin32]::PostMessage($w.Handle,0x0010,[IntPtr]::Zero,[IntPtr]::Zero)}elseif($w.Title -eq 'Confirm'){[void][CnwlTemplateIdWin32]::PostMessage($w.Handle,0x0100,[IntPtr]0x0D,[IntPtr]::Zero);[void][CnwlTemplateIdWin32]::PostMessage($w.Handle,0x0101,[IntPtr]0x0D,[IntPtr]::Zero)}};Start-Sleep -Milliseconds 500};if(-not(Test-Path $result)){throw 'Identity probe produced no result.'};$lines=Get-Content $result;if($lines -notcontains 'status=PASS_TEMPLATE_IDENTITY_DISCOVERY'){throw "Identity discovery failed:`n$($lines -join "`n")"}}finally{if(-not$p.HasExited){Stop-Process $p.Id -Force -ErrorAction SilentlyContinue};Remove-Item Env:CNWL_YMM4_TEMPLATE_ID_DIR -ErrorAction SilentlyContinue}
